  RS b_status = static_cast<RS>(static_cast<int>(*FUZZ_PARAM(unsigned int) % (max_status + 1)));
  a.response_status = a_status;
  b.response_status = b_status;

  // Fuzz revocation_status across a small bounded domain. The exact enum values are
  // library-defined; we assume a compact 0..2 domain (GOOD/UNKNOWN/REVOKED) and cast.
  int rev_dom = 3;
  a.revocation_status = static_cast<bssl::OCSPRevocationStatus>(static_cast<int>(*FUZZ_PARAM(unsigned int) % rev_dom));
  b.revocation_status = static_cast<bssl::OCSPRevocationStatus>(static_cast<int>(*FUZZ_PARAM(unsigned int) % rev_dom));

  // Basic properties the operator must satisfy:
  // 1) Reflexivity
  FUZZ_ASSERT((a == a), "OCSPVerifyResult equality must be reflexive");
  FUZZ_ASSERT((b == b), "OCSPVerifyResult equality must be reflexive");

  // 2) Symmetry
  bool ab = (a == b);
  bool ba = (b == a);
  FUZZ_ASSERT(ab == ba, "OCSPVerifyResult equality must be symmetric");

  // 3) When response_status != PROVIDED, revocation_status must not affect equality.
  if (a.response_status != RS::PROVIDED) {
    bssl::OCSPVerifyResult a2 = a;
    // Change revocation_status to a different value while keeping response_status the same.
    int alt = (static_cast<int>(a2.revocation_status) + 1) % rev_dom;
    a2.revocation_status = static_cast<bssl::OCSPRevocationStatus>(alt);
    FUZZ_ASSERT((a == a2), "revocation_status must be ignored unless status is PROVIDED");
  }
  if (b.response_status != RS::PROVIDED) {
    bssl::OCSPVerifyResult b2 = b;
    int alt = (static_cast<int>(b2.revocation_status) + 2) % rev_dom;
    b2.revocation_status = static_cast<bssl::OCSPRevocationStatus>(alt);
    FUZZ_ASSERT((b == b2), "revocation_status must be ignored unless status is PROVIDED");
  }

