import base64
import os
import random
import struct
from typing import List

# We generate a valid X.509 certificate in either PEM or DER form.
# To maximize successful parsing across implementations, we embed a minimal,
# self-signed v3 TBSCertificate using well-formed DER with reasonable defaults.
# The generator emits either:
# - PEM: -----BEGIN CERTIFICATE----- base64(DER) -----END CERTIFICATE-----
# - DER: raw DER bytes
# Selection and a few fields are randomized but remain valid.

# Helper: minimal ASN.1 DER encoding routines

def _der_len(length: int) -> bytes:
    if length < 0x80:
        return bytes([length])
    s = []
    while length > 0:
        s.append(length & 0xFF)
        length >>= 8
    s.reverse()
    return bytes([0x80 | len(s)]) + bytes(s)


def _der_tlv(tag: int, value: bytes) -> bytes:
    return bytes([tag]) + _der_len(len(value)) + value


def _der_seq(contents: bytes) -> bytes:
    return _der_tlv(0x30, contents)


def _der_set(contents: bytes) -> bytes:
    return _der_tlv(0x31, contents)


def _der_int(n: int) -> bytes:
    if n == 0:
        enc = b"\x00"
    else:
        tmp = []
        while n > 0:
            tmp.append(n & 0xFF)
            n >>= 8
        tmp.reverse()
        enc = bytes(tmp)
        if enc[0] & 0x80:
            enc = b"\x00" + enc
    return _der_tlv(0x02, enc)


def _der_null() -> bytes:
    return b"\x05\x00"


def _der_oid(oid: List[int]) -> bytes:
    assert len(oid) >= 2
    first = 40 * oid[0] + oid[1]
    out = [first]
    for v in oid[2:]:
        # base-128, MSB continuation
        stack = [v & 0x7F]
        v >>= 7
        while v:
            stack.append(0x80 | (v & 0x7F))
            v >>= 7
        out.extend(reversed(stack))
    return _der_tlv(0x06, bytes(out))


def _der_utctime(ts: int) -> bytes:
    # YYMMDDhhmmssZ; limit years to 1950-2049; we map given ts accordingly.
    import time
    tm = time.gmtime(ts)
    year = tm.tm_year
    if year < 1950:
        year = 2000
    if year >= 2050:
        year = 2049
    yy = year % 100
    s = f"{yy:02d}{tm.tm_mon:02d}{tm.tm_mday:02d}{tm.tm_hour:02d}{tm.tm_min:02d}{tm.tm_sec:02d}Z".encode()
    return _der_tlv(0x17, s)


def _der_printable_string(s: str) -> bytes:
    return _der_tlv(0x13, s.encode('ascii'))


def _der_bit_string(bits: bytes) -> bytes:
    # zero unused bits
    return _der_tlv(0x03, b"\x00" + bits)


def _der_octet_string(b: bytes) -> bytes:
    return _der_tlv(0x04, b)


def _der_context(tag: int, value: bytes, constructed=True) -> bytes:
    # tag in [0..31]
    t = (0xA0 if constructed else 0x80) + tag
    return _der_tlv(t, value)


def _der_algo_id(oid: List[int]) -> bytes:
    # AlgorithmIdentifier ::= SEQUENCE { algorithm OBJECT IDENTIFIER, parameters ANY DEFINED BY algorithm OPTIONAL }
    # For rsaEncryption, parameters are NULL; for sha256WithRSAEncryption, NULL as well.
    return _der_seq(_der_oid(oid) + _der_null())

# Simple SHA-256 and RSA key generation are complex to implement here. Instead,
# we use the widely-accepted "NULL subjectPublicKeyInfo" workaround? Not valid.
# Therefore, we embed a known, tiny RSA public key pair with fixed values which is
# sufficient for parsing (verification not required when merely loading certs).
# We'll include a precomputed, self-signed certificate template and vary serial,
# validity, and subject/issuer attributes while keeping signature fields coherent
# enough to parse. X.509 parsing generally does not verify signature on load.

# The following public key parameters (RSA 1024) are compact but standard.
# n and e encoded as DER INTEGERs inside RSAPublicKey (per RFC 3279 SPKI rsa).

_RSA_N_HEX = (
    "B9A1B6A0F8B0F5E0F4D7D2A1C9E3A4B5C6D7E8F9AABBCCDDEEFF1122334455"
    "66778899AABBCCDDEEF00112233445566778899AABBCCDDEEFF001122334455"
)
# Ensure odd length alignment by adding a leading 00 if high bit set; we handle in _der_int.

_RSA_E = 65537


def _hex_to_int(h: str) -> int:
    return int(h, 16)


def _der_rsa_spki(n_int: int, e_int: int) -> bytes:
    # RSAPublicKey ::= SEQUENCE { modulus INTEGER, publicExponent INTEGER }
    rsa_pub = _der_seq(_der_int(n_int) + _der_int(e_int))
    algo = _der_algo_id([1, 2, 840, 113549, 1, 1, 1])  # rsaEncryption
    spk = _der_seq(algo + _der_bit_string(rsa_pub))
    return spk


def _der_name(cn_text: str) -> bytes:
    # Name ::= SEQUENCE OF RDNs; RDN ::= SET OF AttributeTypeAndValue
    # Use CN (2.5.4.3) PrintableString
    atv = _der_seq(_der_oid([2, 5, 4, 3]) + _der_printable_string(cn_text))
    rdn = _der_set(atv)
    return _der_seq(rdn)


def _random_cn(rng: random.Random) -> str:
    alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    ln = rng.randint(3, 16)
    return "FUZZCN-" + ''.join(rng.choice(alphabet) for _ in range(ln))


def _build_tbs(rng: random.Random) -> bytes:
    # version v3: [0] EXPLICIT Version
    version = _der_context(0, _der_int(2))  # v3
    serial = _der_int(rng.getrandbits(64) | 1)  # odd non-zero
    sig_alg = _der_algo_id([1, 2, 840, 113549, 1, 1, 11])  # sha256WithRSAEncryption

    now = 1700000000 + rng.randint(-10_000_000, 10_000_000)
    not_before = _der_utctime(now - rng.randint(0, 100000))
    not_after = _der_utctime(now + rng.randint(100000, 2_000_000))
    validity = _der_seq(not_before + not_after)

    cn = _random_cn(rng)
    issuer = _der_name(cn)
    subject = issuer  # self-signed

    spki = _der_rsa_spki(_hex_to_int(_RSA_N_HEX), _RSA_E)

    # Optional extensions: BasicConstraints CA=false, KeyUsage digitalSignature,keyEncipherment
    ext_list = b""
    # BasicConstraints OID 2.5.29.19: SEQUENCE { cA BOOLEAN DEFAULT FALSE }
    bc = _der_seq(b"")  # empty => cA default false
    ext_list += _der_seq(_der_oid([2, 5, 29, 19]) + _der_octet_string(bc))
    # KeyUsage OID 2.5.29.15: BIT STRING
    # digitalSignature(0), keyEncipherment(2)
    ku_bits = bytes([0b00100100])  # bit 0 and 2 set in little index; X.509 uses msb-first in first byte
    ku = _der_bit_string(ku_bits)
    ext_list += _der_seq(_der_oid([2, 5, 29, 15]) + _der_octet_string(ku))
    extensions = _der_seq(ext_list)
    ext_wrapped = _der_context(3, extensions)  # [3] EXPLICIT

    tbs = _der_seq(version + serial + sig_alg + issuer + validity + subject + spki + ext_wrapped)
    return tbs


def _fake_signature(rng: random.Random) -> bytes:
    # Create a syntactically valid ASN.1 BIT STRING as signatureValue; content is arbitrary bytes.
    sig_bytes = rng.randbytes(rng.randint(64, 128)) if hasattr(rng, 'randbytes') else bytes([rng.randrange(256) for _ in range(rng.randint(64, 128))])
    return _der_bit_string(sig_bytes)


def _build_cert_der(rng: random.Random) -> bytes:
    tbs = _build_tbs(rng)
    sig_alg = _der_algo_id([1, 2, 840, 113549, 1, 1, 11])  # sha256WithRSAEncryption
    sig = _fake_signature(rng)
    cert = _der_seq(tbs + sig_alg + sig)
    return cert


def _to_pem(label: str, der: bytes) -> bytes:
    b64 = base64.encodebytes(der).replace(b"\n", b"\n")
    # Wrap at 64 columns
    lines = []
    s = base64.b64encode(der)
    for i in range(0, len(s), 64):
        lines.append(s[i:i+64])
    body = b"\n".join(lines)
    return (b"-----BEGIN " + label.encode() + b"-----\n" + body + b"\n-----END " + label.encode() + b"-----\n")


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    der = _build_cert_der(rng)
    # Randomly choose PEM or DER (roughly half/half)
    if rng.choice([True, False]):
        return _to_pem("CERTIFICATE", der)
    return der
